<script setup lang="ts">
interface Peer{id:string;name:string;avatarUrl:string;level:number}
interface Entry{key:string;conversationId:string;peer:Peer;unreadCount:number;muted:boolean;pinned:boolean;preview?:{text:string}}
interface Message{id:string;conversationId:string;senderId:string;content:string;createdAt:string;editedAt?:string;withdrawnAt?:string;replyTo?:{id:string;content:string;withdrawn:boolean}}
const auth=useAuthStore(),login=useLoginDialog(),rt=useRealtime();
const entries=ref<Entry[]>([]),contacts=ref<Peer[]>([]),selected=ref(''),items=ref<Message[]>([]),query=ref(''),content=ref(''),error=ref(''),busy=ref(false),quoting=ref<Message|null>(null),cursor=ref<string|null>(null),pendingId=ref<string|null>(null);
const timelineBox=ref<HTMLElement|null>(null);
const active=computed(()=>entries.value.find(c=>c.conversationId===selected.value));
const me=computed(()=>String(auth.user?.id||''));
function err(e:unknown){return(e as {data?:{detail?:string}}).data?.detail||'连接失败，请重试';}
async function refresh(){if(!auth.isLogin)return;try{entries.value=(await $fetch<{items:Entry[]}>('/v1/inbox',{query:{limit:50}})).items;}catch(e){error.value=err(e);}}
async function search(){try{contacts.value=(await $fetch<{items:Peer[]}>('/v1/dm/contacts',{query:{q:query.value}})).items;}catch(e){error.value=err(e);}}
async function timeline(older=false){const id=selected.value;if(!id)return;try{const r=await $fetch<{items:{type:string;message:Message}[];nextCursor:string|null}>(`/v1/inbox/dm-${id}/items`,{query:older&&cursor.value?{cursor:cursor.value}:{}});if(selected.value!==id)return;const list=r.items.map(i=>i.message).reverse();items.value=older?[...list,...items.value]:list;cursor.value=r.nextCursor;await nextTick();if(!older&&timelineBox.value)timelineBox.value.scrollTop=timelineBox.value.scrollHeight;await $fetch(`/v1/inbox/dm-${id}/read`,{method:'POST'});await refresh();}catch(e){error.value=err(e);}}
async function choose(id:string){selected.value=id;items.value=[];quoting.value=null;await timeline();}
async function start(p:Peer){try{const c=await $fetch<{id:string}>('/v1/dm/direct',{method:'POST',body:{userId:p.id}});await refresh();await choose(c.id);}catch(e){error.value=err(e);}}
async function send(){if(busy.value||!content.value.trim()||!selected.value)return;busy.value=true;error.value='';pendingId.value ||= crypto.randomUUID();try{await $fetch(`/v1/dm/conversations/${selected.value}/messages`,{method:'POST',body:{content:content.value,clientId:pendingId.value,replyToId:quoting.value?.id}});content.value='';pendingId.value=null;quoting.value=null;await timeline();}catch(e){error.value=err(e);}finally{busy.value=false;}}
async function change(m:Message,withdraw=false){if(withdraw&&!confirm('撤回这条消息？'))return;const value=withdraw?null:prompt('编辑消息',m.content);if(!withdraw&&value===null)return;try{await $fetch(`/v1/dm/messages/${m.id}`,{method:withdraw?'DELETE':'PATCH',...(withdraw?{}:{body:{content:value}})});await timeline();}catch(e){error.value=err(e);}}
async function preference(key:'muted'|'pinned'){if(!active.value)return;try{await $fetch(`/v1/dm/conversations/${selected.value}`,{method:'PATCH',body:{[key]:!active.value[key]}});await refresh();}catch(e){error.value=err(e);}}
let off:(()=>void)|undefined;
onMounted(()=>{if(auth.isLogin){refresh();search();}off=rt.on('*',event=>{if(['dm.message.created','dm.message.edited','dm.message.withdrawn','dm.conversation.updated'].includes(event.t)){refresh();if((event.d as {conversationId?:string})?.conversationId===selected.value&&event.t!=='dm.conversation.updated')timeline();}});});
onBeforeUnmount(()=>off?.());
watch(()=>auth.isLogin,v=>{entries.value=[];items.value=[];contacts.value=[];selected.value='';if(v){refresh();search();}});
</script>
<template><section class="messages"><header><small>KNOCK KNOCK / PRIVATE CHANNEL</small><h1>敲敲</h1><p>私聊 · 消息记录 · 引用 · 编辑 · 撤回</p></header><button v-if="!auth.isLogin" @click="login.open()">登录后使用敲敲</button><p v-if="error" role="alert">{{ error }}</p><div v-if="auth.isLogin" class="workspace"><aside><h2>通讯录</h2><form @submit.prevent="search"><input v-model="query" aria-label="搜索用户" placeholder="账号或昵称"><button>查找</button></form><div class="contact-list"><button v-for="p in contacts" :key="p.id" @click="start(p)"><img :src="p.avatarUrl" alt="">{{ p.name }}<small>Lv.{{ p.level }}</small></button></div><h2>最近会话</h2><button @click="refresh">刷新会话</button><button v-for="c in entries" :key="c.key" class="conversation" :aria-pressed="selected===c.conversationId" @click="choose(c.conversationId)"><b>{{ c.pinned?'⌖ ':'' }}{{ c.peer.name }}</b><span>{{ c.preview?.text }}</span><small>{{ c.unreadCount ? `${c.unreadCount} 未读` : '已读' }} {{ c.muted?'· 免打扰':'' }}</small></button></aside><article><template v-if="active"><header><h2>{{ active.peer.name }}</h2><button @click="preference('pinned')">{{ active.pinned?'取消置顶':'置顶' }}</button><button @click="preference('muted')">{{ active.muted?'取消免打扰':'免打扰' }}</button><NuxtLink :to="`/profile/${active.peer.id}`">个人空间</NuxtLink></header><button v-if="cursor" @click="timeline(true)">加载更早消息</button><div ref="timelineBox" class="timeline" aria-live="polite"><div v-for="m in items" :key="m.id" class="bubble" :class="{mine:m.senderId===me}"><small>{{ m.senderId===me?'我':active.peer.name }} · {{ m.createdAt }} {{ m.editedAt?'· 已编辑':'' }}</small><blockquote v-if="m.replyTo">{{ m.replyTo.withdrawn?'引用消息已撤回':m.replyTo.content }}</blockquote><p>{{ m.withdrawnAt?'消息已撤回':m.content }}</p><div v-if="!m.withdrawnAt"><button @click="quoting=m">引用</button><template v-if="m.senderId===me"><button @click="change(m)">编辑</button><button @click="change(m,true)">撤回</button></template></div></div><p v-if="!items.length">还没有消息，打个招呼吧。</p></div><p v-if="quoting">引用：{{ quoting.content }} <button @click="quoting=null">取消</button></p><form class="composer" @submit.prevent="send"><textarea v-model="content" aria-label="消息内容" maxlength="10000" placeholder="发送消息…" @input="rt.sendTyping(selected)"/><button :disabled="busy||!content.trim()">{{ busy?'发送中…':'发送' }}</button></form></template><p v-else>选择通讯录中的用户，开始私聊。</p></article></div></section></template>
<style scoped>
.messages{max-width:1500px;margin:auto;padding:22px 18px 110px;color:#dce1d4}.messages h1{font-size:36px;color:#d7fa00}.workspace{display:grid;grid-template-columns:300px minmax(0,1fr);gap:18px}.workspace aside,.workspace article{padding:18px;background:#202220;border:2px solid #3c4038;border-radius:22px;min-width:0}.messages button{background:#22281d;color:#dce6cd;border:1px solid #5f6c4b;border-radius:18px;padding:8px 12px;margin:3px;cursor:pointer}.messages input,.messages textarea{background:#10120e;color:#eee;border:1px solid #526344;border-radius:12px;padding:12px;max-width:100%;box-sizing:border-box}.contact-list{max-height:220px;overflow:auto}.contact-list button{display:flex;width:calc(100% - 6px);align-items:center;gap:8px}.contact-list img{width:28px;height:28px;border-radius:50%}.contact-list small{margin-left:auto}.conversation{display:flex;width:calc(100% - 6px);flex-direction:column;gap:5px;align-items:flex-start}.conversation span{max-width:100%;overflow:hidden;text-overflow:ellipsis;white-space:nowrap}.conversation[aria-pressed=true]{border-color:#d7fa00}.timeline{height:440px;overflow:auto;padding:12px}.bubble{margin:12px 0;background:#141710;border-radius:16px;padding:12px;max-width:85%;overflow-wrap:anywhere}.bubble.mine{margin-left:auto;border:1px solid #758345}.bubble p{white-space:pre-wrap}.bubble small{font-size:10px;color:#9ca58c}.bubble button{font-size:10px}.composer{display:flex;gap:8px}.composer textarea{flex:1;min-width:0}.messages a{color:#d7fa00}.messages [role=alert]{color:#ffad96}.messages blockquote{border-left:3px solid #7d8764;margin:4px;padding-left:10px;color:#9da48e}@media(max-width:768px){.workspace{grid-template-columns:1fr}.timeline{height:360px}.contact-list{max-height:130px}.workspace aside{max-height:330px;overflow:auto}.messages{padding:12px 8px 110px}}
</style>
